// Generated by Agent Team Kit 0.16.0. Do not edit.
// The team as a graph, for the dashboard: every role from the briefs with its band, manager, reports, pool parent,
// the paths it owns (from ownership.md) and the hand-off edges between roles (from each brief's "Hands to" line).
//
//   import { buildGraph } from './roster-graph.mjs'; buildGraph('docs/team')
//   graphFrom(briefs, ownershipMarkdown)   the same from parsed briefs (briefs.mjs parseBrief) and ownership.md's text
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadBriefs } from './briefs.mjs';

const clean = (s) => s.replace(/\([^)]*\)/g, '').replace(/[`*]/g, '').replace(/\s+/g, ' ').trim();
const words = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const label = (key) => key.replace(/-/g, ' ').replace(/^./, (c) => c.toUpperCase());
const BAND_ORDER = ['executive', 'product', 'engineering', 'quality', 'operations', 'insights', 'go-to-market', 'customer', 'corporate'];

/** Phrases briefs use for sets of roles, resolved against the roles that exist. */
function aliases(slugs) {
  const has = (s) => slugs.includes(s);
  const devs = slugs.filter((s) => /^(web|mobile|android|ios)-dev$/.test(s));
  const qa = slugs.filter((s) => /^qa-/.test(s));
  const a = {
    owner: ['owner'],
    'platform devs': devs, 'platform dev': devs, 'owning dev': devs, 'the owning dev': devs,
    'its qa': qa, 'qa roles': qa, 'qa': qa,
    'style threads': has('style-thread') ? ['style-thread'] : [],
    infra: has('infra-secrets-oncall') ? ['infra-secrets-oncall'] : [],
    'customer success': has('customer-success-lead') ? ['customer-success-lead'] : [],
    'legal owner': has('legal-privacy-owner') ? ['legal-privacy-owner'] : [],
    legal: has('legal-privacy-owner') ? ['legal-privacy-owner'] : [],
  };
  return Object.fromEntries(Object.entries(a).filter(([, v]) => v.length));
}

export function resolveTargets(raw, byTitle, alias) {
  const out = new Set();
  const unresolved = [];
  const lookup = (p) => {
    const q = p.replace(/^(the|both|its|a)\s+/, '').trim();
    for (const c of [p, q, q.replace(/s$/, '')]) {
      if (alias[c]) return alias[c];
      if (byTitle.has(c)) return [byTitle.get(c)];
      if (byTitle.has(words(c))) return [byTitle.get(words(c))];
    }
    return null;
  };
  const phrases = clean(raw).toLowerCase().split(/[,;]|\bthen\b/).map((p) => p.trim()).filter(Boolean)
    .map((p) => p.split(/\s+(?:when|before|as|for|via|with)\s+/)[0].trim());
  for (const p of phrases) {
    const parts = lookup(p) ? [p] : p.split(/\s+and\s+/);
    for (const part of parts) {
      const hit = lookup(part);
      if (hit) hit.forEach((s) => out.add(s)); else if (part) unresolved.push(part);
    }
  }
  return { slugs: [...out], unresolved };
}

export function parseOwnership(md) {
  const rows = [];
  for (const line of md.split('\n')) {
    const cells = line.split('|').map((c) => c.trim());
    if (cells.length < 4 || !cells[1].startsWith('`')) continue;
    rows.push({ paths: [...cells[1].matchAll(/`([^`]+)`/g)].map((m) => m[1]), writer: cells[2] });
  }
  return rows;
}

export function buildGraph(teamDir) {
  const ownershipFile = join(teamDir, 'ownership.md');
  return graphFrom(loadBriefs(join(teamDir, 'roles')), existsSync(ownershipFile) ? readFileSync(ownershipFile, 'utf8') : '');
}

export function graphFrom(briefs, ownership = '') {
  const slugs = briefs.map((b) => b.slug);
  const alias = aliases(slugs);
  const byTitle = new Map();
  for (const b of briefs) { byTitle.set(b.title.toLowerCase(), b.slug); byTitle.set(b.slug, b.slug); byTitle.set(b.slug.replace(/-/g, ' '), b.slug); }
  const bySlug = new Map();
  const top = slugs.find((s) => briefs.find((b) => b.slug === s).reportsTo === 'owner') ?? slugs[0];
  const roles = briefs.map((b) => ({
    slug: b.slug,
    title: b.title,
    titleNote: /\(([^)]*)\)/.exec(b.heading)?.[1] ?? '',
    model: b.model,
    tier: b.tier,
    group: b.group || 'other',
    dormant: b.status === 'dormant',
    statusNote: b.statusLine,
    identity: b.identity,
    owns: b.owns,
    tools: b.tools,
    wakesOn: b.wakesOn,
    rules: b.rules,
    reportsTo: b.reportsTo === 'owner' || slugs.includes(b.reportsTo) ? b.reportsTo : (b.slug === top ? 'owner' : top),
    reportsToDeclared: b.reportsTo === 'owner' || slugs.includes(b.reportsTo),
    directReports: b.directReports,
    handsToRaw: b.handsTo,
    pool: /short-lived|one .* per /i.test(b.heading) ? { parent: b.reportsTo } : null,
    paths: [],
  }));
  for (const r of roles) bySlug.set(r.slug, r);
  // Reports, in the order a lead's "Direct reports" lists them, then executives, then roster order.
  for (const r of roles) r.reports = [];
  const ownerReports = [];
  for (const r of roles) (r.reportsTo === 'owner' ? ownerReports : bySlug.get(r.reportsTo).reports).push(r.slug);
  const exec = (s) => (bySlug.get(s)?.group === 'executive' ? 0 : 1);
  for (const r of roles) {
    const first = r.directReports;
    const rank = (x) => { const i = first.indexOf(x); return i < 0 ? first.length : i; };
    r.reports.sort((a, b) => rank(a) - rank(b) || exec(a) - exec(b) || slugs.indexOf(a) - slugs.indexOf(b));
  }
  const edges = [];
  const unresolved = [];
  for (const r of roles) {
    const peers = roles.filter((x) => x !== r && x.reportsTo === r.reportsTo && x.reportsTo !== 'owner').map((x) => x.slug);
    const execs = roles.filter((x) => x !== r && x.group === 'executive' && x.reportsTo !== 'owner').map((x) => x.slug);
    const special = { 'the direct reports': r.reports, 'direct reports': r.reports, 'other executives': peers, executives: execs };
    const found = [];
    const rest = r.handsToRaw.replace(/\b(the direct reports|direct reports|other executives|executives)\b/gi, (m) => { found.push(...special[m.toLowerCase()]); return ''; });
    const { slugs: hit, unresolved: u } = resolveTargets(rest, byTitle, alias);
    r.handsTo = [...new Set(found.concat(hit))].filter((s) => s !== r.slug);
    for (const to of r.handsTo) edges.push({ from: r.slug, to });
    for (const p of u) unresolved.push({ role: r.slug, phrase: p });
    delete r.handsToRaw;
  }
  for (const row of parseOwnership(ownership)) {
    for (const s of resolveTargets(row.writer.split(/;|\bfrom\b/)[0], byTitle, alias).slugs) bySlug.get(s)?.paths.push(...row.paths);
  }
  const seen = [...new Set(roles.map((r) => r.group))];
  const groups = seen.sort((a, b) => {
    const ia = BAND_ORDER.indexOf(a), ib = BAND_ORDER.indexOf(b);
    return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib) || seen.indexOf(a) - seen.indexOf(b);
  }).map((key) => ({ key, label: label(key) }));
  return { roles, groups, edges, ownerReports, unresolved };
}
